import { useEffect, useRef, useState } from "react";
import api from "@/utils/api";
import { Card, CardContent } from "@/components/ui/card";
import { Loader2, Briefcase, Users, FileText, Download } from "lucide-react";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import Papa from "papaparse";
import { saveAs } from "file-saver";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
} from "recharts";
import useAdminApi from "@/hooks/useAdminApi";

const StatResumePage = () => {
  const api = useAdminApi(); // 🔐 Instance axios avec token
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [year, setYear] = useState(new Date().getFullYear());
  const [month, setMonth] = useState("");
  const exportRef = useRef();

  useEffect(() => {
    const fetchStats = async () => {
        try {
          const res = await api.get("/admin/stats/resume");
          setData(res.data);
        } catch (err) {
          console.error("Erreur chargement stats :", err);
        }
      };

      fetchStats();
    }, [api]);

  const fetchStats = async () => {
    setLoading(true);
    try {
      const params = {};
      if (year) params.year = year;
      if (month) params.month = month;

      const res = await api.get("/admin/stats/resume", { params });
      setStats(res.data);
    } catch (err) {
      console.error("Erreur chargement stats résumé :", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStats();
  }, [year, month]);

    const handleExportPDF = async () => {
        const element = exportRef.current;
        const canvas = await html2canvas(element, {
            scale: 2,
            useCORS: true,
        });

        const imgData = canvas.toDataURL("image/png");
        const pdf = new jsPDF("p", "mm", "a4");

        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();

        const imgHeight = (canvas.height * pdfWidth) / canvas.width;

        let heightLeft = imgHeight;
        let position = 0;

        pdf.addImage(imgData, "PNG", 0, position, pdfWidth, imgHeight);
        heightLeft -= pdfHeight;

        while (heightLeft > 0) {
            position = heightLeft - imgHeight;
            pdf.addPage();
            pdf.addImage(imgData, "PNG", 0, position, pdfWidth, imgHeight);
            heightLeft -= pdfHeight;
        }

        pdf.save(`stats-${year}${month ? `-${month}` : ""}.pdf`);
    };

  const handleExportCSV = () => {
    const csvData = [];

    // 1. Statistiques globales
    csvData.push(["Statistiques globales"]);
    csvData.push(["Candidatures", stats.total_candidatures]);
    csvData.push(["Utilisateurs", stats.total_utilisateurs]);
    csvData.push(["Offres", stats.total_offres]);
    csvData.push([]);

    // 2. Par mois
    csvData.push(["Candidatures par mois"]);
    csvData.push(["Mois", "Total"]);
    stats.candidatures_par_mois?.forEach((item) => {
        csvData.push([item.mois, item.total]);
    });
    csvData.push([]);

    // 3. Par offre
    csvData.push(["Candidatures par offre"]);
    csvData.push(["Offre", "Total"]);
    stats.candidatures_par_offre?.forEach((item) => {
        csvData.push([item.titre, item.total]);
    });
    csvData.push([]);

    // 4. Par type de contrat
    csvData.push(["Répartition par type de contrat"]);
    csvData.push(["Type de contrat", "Total"]);
    stats.par_type_contrat?.forEach((item) => {
        csvData.push([item.type_contrat, item.total]);
    });
    csvData.push([]);

    // 5. Par lieu
    csvData.push(["Top 5 régions avec le plus d’offres"]);
    csvData.push(["Lieu", "Total"]);
    stats.par_lieu?.forEach((item) => {
        csvData.push([item.lieu, item.total]);
    });
    csvData.push([]);

    // 6. Par catégorie
    csvData.push(["Répartition par catégorie"]);
    csvData.push(["Catégorie", "Total"]);
    stats.par_categorie?.forEach((item) => {
        csvData.push([item.categorie, item.total]);
    });

    const csvString = Papa.unparse(csvData);
    const blob = new Blob([csvString], { type: "text/csv;charset=utf-8" });
    saveAs(blob, `stats-resume-${year}${month ? `-${month}` : ""}.csv`);
    };

  const months = ["01","02","03","04","05","06","07","08","09","10","11","12"];

  return (
    <div className="space-y-6 px-4 py-8">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <h1 className="text-2xl font-semibold">Résumé des statistiques</h1>

        <div className="flex gap-3 items-center">
          <select
            value={year}
            onChange={(e) => setYear(e.target.value)}
            className="border rounded px-2 py-1 text-sm"
          >
            {[2025, 2024, 2023, 2022].map((y) => (
              <option key={y} value={y}>
                {y}
              </option>
            ))}
          </select>

          <select
            value={month}
            onChange={(e) => setMonth(e.target.value)}
            className="border rounded px-2 py-1 text-sm"
          >
            <option value="">Tous les mois</option>
            {months.map((m) => (
              <option key={m} value={m}>
                {m}
              </option>
            ))}
          </select>

            <button
                onClick={handleExportPDF}
                className="bg-primary text-white px-3 py-1 rounded flex items-center gap-1 text-sm"
                 >
                <Download className="w-4 h-4" /> Exporter PDF
            </button>
            <button
                onClick={handleExportCSV}
                className="bg-green-600 text-white px-3 py-1 rounded flex items-center gap-1 text-sm"
                >
                <Download className="w-4 h-4" /> Exporter CSV
            </button>
            <button
                onClick={() => window.print()}
                className="bg-slate-700 text-white px-3 py-1 rounded flex items-center gap-1 text-sm no-print"
                >
                <Download className="w-4 h-4" /> Imprimer
            </button>
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center items-center h-32">
          <Loader2 className="animate-spin w-6 h-6 text-muted" />
          <span className="ml-2">Chargement...</span>
        </div>
      ) : !stats ? (
        <p className="text-red-500">Aucune donnée à afficher.</p>
      ) : (
        <div ref={exportRef} className="space-y-10">
          {/* 📊 Cartes principales */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Card className="border-l-4 border-primary shadow-sm">
              <CardContent className="p-6 flex items-center justify-between">
                <div>
                  <p className="text-muted-foreground">Candidatures</p>
                  <p className="text-3xl font-bold">{stats.total_candidatures}</p>
                </div>
                <FileText className="w-8 h-8 text-primary" />
              </CardContent>
            </Card>

            <Card className="border-l-4 border-green-500 shadow-sm">
              <CardContent className="p-6 flex items-center justify-between">
                <div>
                  <p className="text-muted-foreground">Utilisateurs</p>
                  <p className="text-3xl font-bold">{stats.total_utilisateurs}</p>
                </div>
                <Users className="w-8 h-8 text-green-500" />
              </CardContent>
            </Card>

            <Card className="border-l-4 border-blue-500 shadow-sm">
              <CardContent className="p-6 flex items-center justify-between">
                <div>
                  <p className="text-muted-foreground">Offres</p>
                  <p className="text-3xl font-bold">{stats.total_offres}</p>
                </div>
                <Briefcase className="w-8 h-8 text-blue-500" />
              </CardContent>
            </Card>
          </div>

          {/* 📊 Graphique BarChart */}
          <div className="bg-white rounded-xl p-4 shadow-sm border">
             <div className="print-section">
                <h2 className="text-lg font-semibold mb-2">Candidatures par mois</h2>
                {stats.candidatures_par_mois?.length > 0 ? (
                <ResponsiveContainer width="100%" height={300}>
                    <BarChart data={stats.candidatures_par_mois}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="mois" />
                    <YAxis />
                    <Tooltip />
                    <Bar dataKey="total" fill="#2563eb" />
                    </BarChart>
                </ResponsiveContainer>
                ) : (
                <p className="text-muted-foreground">Aucune donnée disponible.</p>
                )}
             </div>
          </div>

          {/* 📋 Tableau des candidatures par offre */}
          <div className="bg-white rounded-xl p-4 shadow-sm border">
                <div className="print-section">
                    <h2 className="text-lg font-semibold mb-2">Candidatures par offre</h2>
                    {stats.candidatures_par_offre?.length > 0 ? (
                    <table className="w-full text-sm border-collapse">
                        <thead>
                        <tr className="bg-muted text-left">
                            <th className="p-2 border-b">Offre</th>
                            <th className="p-2 border-b">Total</th>
                        </tr>
                        </thead>
                        <tbody>
                        {stats.candidatures_par_offre.map((row, i) => (
                            <tr key={i} className="border-b hover:bg-gray-50">
                            <td className="p-2">{row.titre}</td>
                            <td className="p-2">{row.total}</td>
                            </tr>
                        ))}
                        </tbody>
                    </table>
                    ) : (
                    <p className="text-muted-foreground">Aucune donnée disponible.</p>
                    )}
                </div>  
            </div>
   
            {/* 📈 Stats par type de contrat */}
            <div className="bg-white rounded-xl p-4 shadow-sm border">
                <div className="print-section">
                    <h2 className="text-lg font-semibold mb-2">Répartition par type de contrat</h2>
                    {stats.par_type_contrat?.length > 0 ? (
                        <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={stats.par_type_contrat}>
                            <CartesianGrid strokeDasharray="3 3" />
                            <XAxis dataKey="type_contrat" />
                            <YAxis />
                            <Tooltip />
                            <Bar dataKey="total" fill="#16a34a" />
                        </BarChart>
                        </ResponsiveContainer>
                    ) : (
                        <p className="text-muted-foreground">Aucune donnée disponible.</p>
                    )}
                </div>  
            </div>

            {/* 📍 Stats par lieu (top 5) */}
            <div className="bg-white rounded-xl p-4 shadow-sm border">
                <div className="print-section">
                    <h2 className="text-lg font-semibold mb-2">Top 5 régions avec le plus d’offres</h2>
                    <ul className="text-sm">
                        {stats.par_lieu?.map((item, i) => (
                        <li key={i} className="flex justify-between border-b py-1">
                            <span>{item.lieu}</span>
                            <span className="font-semibold">{item.total}</span>
                        </li>
                        ))}
                    </ul> 
                </div>  
            </div>

            {/* 🧾 Stats par catégorie */}
            <div className="bg-white rounded-xl p-4 shadow-sm border">
                <div className="print-section">
                    <h2 className="text-lg font-semibold mb-2">Répartition par catégorie</h2>
                    <ul className="text-sm">
                        {stats.par_categorie?.map((item, i) => (
                        <li key={i} className="flex justify-between border-b py-1">
                            <span>{item.categorie}</span>
                            <span className="font-semibold">{item.total}</span>
                        </li>
                        ))}
                    </ul>
                </div>  
            </div>
              {/* 📊 Comparaison multi-années */}
              <div className="bg-white rounded-xl p-4 shadow-sm border">
                <div className="print-section">
                  <h2 className="text-lg font-semibold mb-2">
                    Évolution mensuelle ({year} vs {Number(year) + 1})
                  </h2>
                  {stats.multi_year_data ? (
                    <ResponsiveContainer width="100%" height={300}>
                      <BarChart
                        data={Array.from({ length: 12 }, (_, i) => {
                          const mois = String(i + 1).padStart(2, "0");
                          const nextYear = String(Number(year) + 1);
                          return {
                            mois,
                            [year]: stats.multi_year_data.find(
                              (d) => d.annee === String(year) && d.mois === mois
                            )?.total || 0,
                            [nextYear]: stats.multi_year_data.find(
                              (d) => d.annee === nextYear && d.mois === mois
                            )?.total || 0,
                          };
                        })}
                      >
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="mois" />
                        <YAxis />
                        <Tooltip />
                        <Bar dataKey={String(year)} fill="#6366f1" />
                        <Bar dataKey={String(Number(year) + 1)} fill="#f97316" />
                      </BarChart>
                    </ResponsiveContainer>
                  ) : (
                    <p className="text-muted-foreground">Aucune donnée disponible.</p>
                  )}
                </div>
              </div>          
            </div>
         )}
    </div>
  );
};

export default StatResumePage;
