import Offres from "@/pages/public/Offres";
import OffreDetail from "@/pages/public/OffreDetail";
import Postuler from "@/pages/public/Postuler";
import { Navigate, useParams } from "react-router-dom";

// 🔁 Redirection propre
function RedirectOffre() {
  const { id } = useParams();
  return <Navigate to={`/offres/${id}`} replace />;
}

const offresRoutes = [
  { path: "/offres", element: <Offres />, label: "Offres" },
  { path: "/offres/:id", element: <OffreDetail /> },
  { path: "/postuler/:id", element: <Postuler /> },
  { path: "/offre/:id", element: <RedirectOffre /> }, // 🧭 redirection activée
];

export default offresRoutes;
