import { useEffect, useState } from "react";
import {
  ajouterImageGalerie,
  supprimerImageGalerie,
  fetchGalerie,
  fetchCategoriesGalerie,
  modifierImageGalerie,
} from "@/utils/adminApi";
import { toast } from "react-toastify";
import { Trash2, UploadCloud, Pencil, XCircle } from "lucide-react";

export default function AdminGalerie() {
  const [images, setImages] = useState([]);
  const [imageFile, setImageFile] = useState(null);
  const [categorie, setCategorie] = useState("");
  const [titre, setTitre] = useState("");
  const [preview, setPreview] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [categories, setCategories] = useState([]);
  const [filtreCategorie, setFiltreCategorie] = useState("");

  const BASE_URL = import.meta.env.PROD
    ? "https://cdotchad.com/api"
    : "http://localhost:5000";

  const chargerImages = async () => {
    try {
      const data = await fetchGalerie();
      setImages(data);
    } catch {
      toast.error("Erreur de chargement des images");
    }
  };

  const chargerCategories = async () => {
    try {
      const data = await fetchCategoriesGalerie();
      setCategories(data);
    } catch {
      toast.error("Erreur de chargement des catégories");
    }
  };

  useEffect(() => {
    chargerImages();
    chargerCategories();
  }, []);

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setImageFile(file);
    setPreview(file ? URL.createObjectURL(file) : null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!categorie || !titre) return toast.error("Tous les champs sont requis");

    try {
      setIsLoading(true);

      if (editingId) {
        await modifierImageGalerie(editingId, { categorie, titre });
        toast.success("Image modifiée !");
      } else {
        if (!imageFile) return toast.error("Veuillez choisir une image.");
        const formData = new FormData();
        formData.append("image", imageFile);
        formData.append("categorie", categorie);
        formData.append("titre", titre);
        await ajouterImageGalerie(formData);
        toast.success("Image ajoutée !");
      }

      resetForm();
      await chargerImages();
      await chargerCategories();
    } catch {
      toast.error("Erreur lors de l’enregistrement");
    } finally {
      setIsLoading(false);
    }
  };

  const resetForm = () => {
    setImageFile(null);
    setCategorie("");
    setTitre("");
    setPreview(null);
    setEditingId(null);
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Supprimer cette image ?")) return;
    try {
      await supprimerImageGalerie(id);
      toast.success("Image supprimée");
      chargerImages();
    } catch {
      toast.error("Erreur lors de la suppression");
    }
  };

  const imagesFiltres = filtreCategorie
    ? images.filter((img) => img.categorie === filtreCategorie)
    : images;

  return (
    <div className="px-6 py-8 max-w-6xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">Gestion de la Galerie</h1>

      <form
        onSubmit={handleSubmit}
        className="bg-white shadow p-4 rounded-lg grid gap-4 mb-8"
      >
        <div>
          <label className="block font-medium mb-1">Titre :</label>
          <input
            type="text"
            className="w-full border rounded p-2"
            value={titre}
            onChange={(e) => setTitre(e.target.value)}
            required
          />
        </div>

        <div>
          <label className="block font-medium mb-1">Catégorie :</label>
          <input
            type="text"
            className="w-full border rounded p-2"
            value={categorie}
            onChange={(e) => setCategorie(e.target.value)}
            required
          />
        </div>

        {!editingId && (
          <div>
            <label className="block font-medium mb-1">Image :</label>
            <input
              type="file"
              accept="image/*"
              onChange={handleImageChange}
              required
            />
            {preview && (
              <img
                src={preview}
                alt="Aperçu"
                className="mt-2 max-h-48 object-cover border rounded"
              />
            )}
          </div>
        )}

        <div className="flex items-center gap-4">
          <button
            type="submit"
            className="flex items-center gap-2 bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
            disabled={isLoading}
          >
            <UploadCloud size={18} />
            {isLoading
              ? "Chargement..."
              : editingId
              ? "Mettre à jour"
              : "Ajouter"}
          </button>

          {editingId && (
            <button
              type="button"
              onClick={resetForm}
              className="flex items-center gap-2 bg-gray-300 text-gray-800 px-4 py-2 rounded hover:bg-gray-400"
            >
              <XCircle size={18} />
              Annuler modification
            </button>
          )}
        </div>
      </form>

      {/* 🔍 Filtre catégorie */}
      {categories.length > 0 && (
        <div className="mb-6">
          <label className="font-medium mr-2">Filtrer par catégorie :</label>
          <select
            value={filtreCategorie}
            onChange={(e) => setFiltreCategorie(e.target.value)}
            className="border rounded p-1"
          >
            <option value="">Toutes</option>
            {categories.map((cat, idx) => (
              <option key={idx} value={cat}>
                {cat}
              </option>
            ))}
          </select>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
        {imagesFiltres.map((img) => (
          <div
            key={img.id}
            className="relative border rounded-lg shadow overflow-hidden"
          >
            <img
              src={img.url}
              alt={img.titre}
              className="w-full h-48 object-cover"
            />
            <div className="p-2">
              <h2 className="text-sm font-semibold">{img.titre}</h2>
              <p className="text-xs text-gray-600">{img.categorie}</p>
            </div>

            <div className="absolute top-2 right-2 flex gap-2">
              <button
                onClick={() => handleDelete(img.id)}
                className="bg-white rounded-full p-1 shadow hover:bg-red-100"
                title="Supprimer"
              >
                <Trash2 size={16} className="text-red-600" />
              </button>

              <button
                onClick={() => {
                  setTitre(img.titre);
                  setCategorie(img.categorie);
                  setEditingId(img.id);
                  setPreview(img.url);
                  setImageFile(null);
                }}
                className="bg-white rounded-full p-1 shadow hover:bg-blue-100"
                title="Modifier"
              >
                <Pencil size={16} className="text-blue-600" />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
